CREATE TABLE truss.preparation_program_registration (program_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, program_identity uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), store_control_id bigint NOT NULL REFERENCES truss.action_store_registration (control_id), store_receipt_bytes bytea NOT NULL CHECK (octet_length(store_receipt_bytes) BETWEEN 1 AND 4194304), registration_key bytea NOT NULL CHECK (octet_length(registration_key) BETWEEN 1 AND 256), compiler_source_pin text NOT NULL CHECK (compiler_source_pin ~ '^[0-9a-f]{40}$'), original_configuration bytea NOT NULL CHECK (octet_length(original_configuration) BETWEEN 1 AND 8388608), original_request bytea NOT NULL CHECK (octet_length(original_request) BETWEEN 1 AND 8388608), original_plan_artifact bytea NOT NULL CHECK (octet_length(original_plan_artifact) BETWEEN 1 AND 8388608), original_binding_artifact bytea NOT NULL CHECK (octet_length(original_binding_artifact) BETWEEN 1 AND 8388608), original_lowering bytea NOT NULL CHECK (octet_length(original_lowering) BETWEEN 1 AND 8388608), issuer_xid xid8 NOT NULL CHECK (issuer_xid > '0'::xid8), issuer_actor_oid oid NOT NULL CHECK (issuer_actor_oid <> '0'::oid), issued_at timestamptz NOT NULL CHECK (isfinite(issued_at)), UNIQUE (store_control_id, registration_key)); CREATE TRIGGER preparation_program_registration_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON truss.preparation_program_registration EXECUTE FUNCTION truss.catalog_immutable(); ALTER TABLE truss.preparation_program_registration ENABLE ALWAYS TRIGGER preparation_program_registration_immutable; REVOKE ALL ON truss.preparation_program_registration FROM public; REVOKE ALL ON SEQUENCE truss.preparation_program_registration_program_id_seq FROM public; REVOKE ALL ON TYPE truss.preparation_program_registration FROM public